      "a_request": "R1",
      "b_asked": "금연구역 안에 흡연구역을 설치할 때 안내표지의 설치 위치",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "흡연구역을 설치하는 경우 해당 장소의 소유자·점유자 또는 관리자는 시민이 잘 알 수 있는 장소에 흡연구역 안내표지판을 설치하여야 한다.",
          "b_ids": "금연:제8조제2항제1호"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "흡연구역의 면적과 위치를 정할 때 고려하는 사항",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "해당 장소의 규모, 특성 및 간접흡연 피해가능성 등을 고려하여 흡연구역의 면적, 위치 등을 정하여야 한다.",
          "b_ids": "금연:제8조제2항제2호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
